import{_ as t,o as e,c as n,a3 as d}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"RAG 与记忆总览","description":"说明 RAG 与记忆模块的作用、学习目标、知识边界和推荐路径。","frontmatter":{"title":"RAG 与记忆总览","description":"说明 RAG 与记忆模块的作用、学习目标、知识边界和推荐路径。"},"headers":[],"relativePath":"py-agent/knowledge/index.md","filePath":"py-agent/knowledge/index.md","lastUpdated":1785318762000}'),r={name:"py-agent/knowledge/index.md"};function i(l,a,o,h,p,s){return e(),n("div",null,[...a[0]||(a[0]=[d(`<h1 id="rag-与记忆总览" tabindex="-1">RAG 与记忆总览 <a class="header-anchor" href="#rag-与记忆总览" aria-label="Permalink to &quot;RAG 与记忆总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本模块解决两个相邻但不同的问题：RAG 让模型在回答前取得外部证据，记忆让应用在一次或多次运行之间保留经过治理的信息。两者都在扩展模型可用上下文，但数据来源、生命周期、写入责任和评测方法并不相同。</p><h2 id="_1-模块作用" tabindex="-1">1. 模块作用 <a class="header-anchor" href="#_1-模块作用" aria-label="Permalink to &quot;1. 模块作用&quot;">​</a></h2><p>“基础与模型”解释模型如何处理上下文，“Agent 开发”解释模型如何选择工具；本模块进一步建立从文档进入知识库、从查询召回证据、从证据生成引用回答，以及从运行状态形成短期和长期记忆的完整数据模型。</p><h2 id="_2-学习目标" tabindex="-1">2. 学习目标 <a class="header-anchor" href="#_2-学习目标" aria-label="Permalink to &quot;2. 学习目标&quot;">​</a></h2><p>完成本模块后，你应该能够：</p><ol><li>区分模型知识、Prompt 上下文、RAG、Agent 记忆和业务数据库；</li><li>解释加载、规范化、切分、Embedding、索引、检索、重排、上下文构建和生成的完整链路；</li><li>为 Chunk、元数据、向量索引、Retriever 和混合检索作出可验证设计；</li><li>使用 LangChain 或 LlamaIndex 实现带来源的 RAG；</li><li>分别评测召回、排序、回答正确性、忠实性和引用质量；</li><li>判断何时需要高级索引、查询改写、纠错、GraphRAG 或 Agentic RAG；</li><li>区分 Checkpointer 与 Store，并设计记忆写入、检索、更新、删除和治理；</li><li>为 RAG 与记忆建立权限、回归、可观测和生产运行边界。</li></ol><h2 id="_3-学习路径" tabindex="-1">3. 学习路径 <a class="header-anchor" href="#_3-学习路径" aria-label="Permalink to &quot;3. 学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>核心问题</th><th>学习结果</th></tr></thead><tbody><tr><td><a href="/py-agent/knowledge/rag-foundations-data/">RAG 原理与数据</a></td><td>RAG 为什么存在，数据怎样成为 Chunk</td><td>建立完整链路和数据入口</td></tr><tr><td><a href="/py-agent/knowledge/index-retrieval/">索引与检索</a></td><td>Chunk 怎样表示、存储和召回</td><td>能设计检索系统</td></tr><tr><td><a href="/py-agent/knowledge/generation-application/">生成与应用</a></td><td>证据怎样成为可验证回答</td><td>能构建引用与对话式 RAG</td></tr><tr><td><a href="/py-agent/knowledge/framework-implementation/">框架实现</a></td><td>通用链路怎样映射到框架</td><td>能使用 LangChain 或 LlamaIndex</td></tr><tr><td><a href="/py-agent/knowledge/rag-quality/">RAG 质量工程</a></td><td>怎样知道系统真的变好</td><td>能评测、测试和运行 RAG</td></tr><tr><td><a href="/py-agent/knowledge/advanced-rag/">高级 RAG</a></td><td>基础链路不足时怎样升级</td><td>能按失败类型选择高级策略</td></tr><tr><td><a href="/py-agent/knowledge/memory/">记忆系统</a></td><td>哪些信息值得跨步骤或跨线程保留</td><td>能设计短期与长期记忆</td></tr></tbody></table><p>建议按表中顺序学习。高级 RAG 不是基础链路的替代品；只有基线评测已经指出具体失败，才有依据增加复杂策略。</p><h2 id="_4-两条数据链路" tabindex="-1">4. 两条数据链路 <a class="header-anchor" href="#_4-两条数据链路" aria-label="Permalink to &quot;4. 两条数据链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RAG：文档 -&gt; Chunk -&gt; 索引 -&gt; 查询 -&gt; 证据 -&gt; 回答</span></span>
<span class="line"><span>记忆：运行事件 -&gt; 写入判断 -&gt; Checkpoint / Store -&gt; 检索 -&gt; 上下文</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>RAG 的权威来源通常是外部文档或业务知识，记忆的来源通常是会话和运行事件。两条链路都必须保留来源、时间、权限和删除能力。</p><h2 id="_5-内容边界" tabindex="-1">5. 内容边界 <a class="header-anchor" href="#_5-内容边界" aria-label="Permalink to &quot;5. 内容边界&quot;">​</a></h2><p>本模块使用 LangChain 作为主要 RAG 实现，LlamaIndex 作为面向数据框架的对照实现，LangGraph 用于解释 Checkpointer 与 Store。它不展开：</p><ul><li>通用 Agent 工具和 Middleware API，参见“Agent 开发”；</li><li>完整 LangGraph 状态图与多 Agent 编排，参见“工作流与多 Agent”；</li><li>企业级部署平台和综合业务架构，参见后续生产与实战模块；</li><li>模型训练、微调和向量模型训练。</li></ul><h2 id="_6-前置知识" tabindex="-1">6. 前置知识 <a class="header-anchor" href="#_6-前置知识" aria-label="Permalink to &quot;6. 前置知识&quot;">​</a></h2><p>开始前应理解 Python 数据结构、类型标注、异步与 HTTP，能够调用聊天模型，并了解 Token、上下文窗口、Embedding 和 Agent 工具的基本概念。</p><h2 id="_7-学习方法" tabindex="-1">7. 学习方法 <a class="header-anchor" href="#_7-学习方法" aria-label="Permalink to &quot;7. 学习方法&quot;">​</a></h2><p>阅读每篇文章时始终追踪四个对象：输入数据、产生的中间结构、下游消费方式和质量验证。代码只用于观察这条数据链路；换用框架或数据库后，这四个对象仍然成立。</p>`,21)])])}const u=t(r,[["render",i]]);export{c as __pageData,u as default};
